import asyncio
from fastmcp.server import create_proxy, FastMCP

async def main():
    backend = FastMCP("Backend Server")

    @backend.tool()
    def example_tool(name: str) -> str:
        """An example tool."""
        return f"Backend processed: {name}"

    @backend.resource()
    def example_resource() -> str:
        """An example resource."""
        return "Backend resource content"

    proxy = create_proxy(backend, name="Transparent Proxy")

    await proxy.run_stdio_async()

if __name__ == "__main__":
    asyncio.run(main())
